package dev.altencir.orders.read;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="order_summaries") public class OrderSummaryEntity {
 @Id @Column(name="order_id") private UUID orderId; @Column(name="customer_id",nullable=false) private String customerId; @Column(name="item_count",nullable=false) private int itemCount; @Column(nullable=false,precision=19,scale=2) private BigDecimal total; @Column(name="source_event_id",nullable=false) private UUID sourceEventId; @Column(name="source_occurred_at",nullable=false) private Instant sourceOccurredAt; @Column(name="projected_at",nullable=false) private Instant projectedAt;
 protected OrderSummaryEntity(){} public OrderSummaryEntity(UUID orderId,String customerId,int itemCount,BigDecimal total,UUID sourceEventId,Instant sourceOccurredAt,Instant projectedAt){this.orderId=orderId;this.customerId=customerId;this.itemCount=itemCount;this.total=total;this.sourceEventId=sourceEventId;this.sourceOccurredAt=sourceOccurredAt;this.projectedAt=projectedAt;}
 public UUID getOrderId(){return orderId;} public String getCustomerId(){return customerId;} public int getItemCount(){return itemCount;} public BigDecimal getTotal(){return total;} public UUID getSourceEventId(){return sourceEventId;} public Instant getSourceOccurredAt(){return sourceOccurredAt;} public Instant getProjectedAt(){return projectedAt;}
}
